<template><view class="app-surround">
<!-- #ifdef H5 --><view class="desktop-header"><view class="brand"><FIcon name="leaf" :size="30"/><text>食材配送</text><text class="brand-sub">新鲜食材，有序送达</text></view><view class="role-links"><button v-for="(label,r) in roles" :key="r" :class="{selected:currentRole===r}" @tap="switchRole(r)">{{label}}</button></view><view class="live-label"><text class="live-dot"/>三端数据同步</view></view><!-- #endif -->
<view class="phone-app">
<!-- #ifdef H5 --><view class="statusbar"><text>9:41</text><view class="row"><FIcon name="signal" :size="14"/><FIcon name="wifi" :size="14"/><FIcon name="battery" :size="18"/></view></view><!-- #endif -->
<!-- #ifndef H5 --><view :style="{height:statusHeight+'px'}"/><!-- #endif -->
<view v-if="!authenticated" class="login-page"><view class="login-logo"><FIcon name="leaf" :size="40"/></view><text class="login-title">食材配送</text><text class="muted">平台定价 · 定向分单 · 线下结算</text><view class="login-roles"><button v-for="(name,r) in roles" :key="r" :class="{active:loginRole===r}" @tap="selectLogin(r)">{{name}}</button></view><view class="card login-form"><text class="h2">{{roles[loginRole]}}登录</text><label class="field"><text>账号</text><input v-model="credentials.username" placeholder="请输入账号" aria-label="账号"/></label><label class="field"><text>密码</text><input v-model="credentials.password" password placeholder="请输入密码" aria-label="密码" @confirm="signIn"/></label><button class="btn full" :disabled="busy" :loading="busy" @tap="signIn">登录</button></view><view class="notice small">体验账号已预填，密码由管理员配置。三端共享同一套订单。</view><view class="center muted small mt24">食材供应链订货与配送管理</view></view>
<template v-else><view class="page-header"><button v-if="!isRoot" class="icon-button" aria-label="返回" @tap="back"><FIcon name="back"/></button><view v-else-if="screen==='home'" class="row strong"><FIcon name="store" :size="20"/>{{currentStore?.name||'门店'}}<FIcon name="down" :size="14"/></view><text v-else class="header-title">{{titles[screen]||'食材配送'}}</text><text v-if="!isRoot" class="header-title centered">{{titles[screen]||'食材配送'}}</text><view class="row"><button v-if="screen==='home'" class="icon-button" aria-label="刷新订单" @tap="refresh()"><FIcon name="bell" :size="20"/></button><!-- #ifdef H5 --><button class="capsule" aria-label="账号设置" @tap="go('settings')"><text>•••</text><text class="capsule-divider">│</text><text>⊙</text></button><!-- #endif --><!-- #ifndef H5 --><button class="icon-button" aria-label="账号设置" @tap="go('settings')"><FIcon name="settings" :size="20"/></button><view style="width:80px;flex-shrink:0"/><!-- #endif --></view></view><view v-if="state.offline" class="connection-warning" @tap="refresh()">连接已断开，点击重试</view><view v-if="state.loading&&!state.products.length&&!state.orders.length" class="page-content"><view v-for="i in 3" :key="i" class="skeleton"/></view><template v-else><view v-if="!authorized" class="empty"><text>当前账号无权访问此页面</text><button class="btn mt16" @tap="go(home(currentRole),{},true)">返回工作台</button></view><StoreScreens v-else-if="storeScreens.includes(screen)" :screen="screen" :item-id="itemId" :filter="filter"/><SupplierScreens v-else-if="supplierScreens.includes(screen)" :screen="screen" :item-id="itemId" :filter="filter"/><AdminScreens v-else :screen="screen" :item-id="itemId" :filter="filter"/></template><view v-if="showNav" class="bottom-nav"><button v-for="item in nav" :key="item.screen" :class="{active:isActive(item)}" @tap="go(item.screen,{},true)"><view class="nav-icon"><FIcon :name="item.icon" :size="23"/><text v-if="item.screen==='cart'&&state.cart.length" class="nav-count">{{state.cart.length}}</text></view><text>{{item.label}}</text></button><view class="home-indicator"/></view></template><view v-if="busy" class="saving-line"/></view>
<!-- #ifdef H5 --><view class="desktop-caption"><text>{{roles[currentRole]}}</text><text>统一定价 · 专属配送 · 线下结算</text></view><!-- #endif -->
</view></template>
<script setup>
import {ref,computed,provide} from 'vue';import FIcon from './FIcon.vue';import StoreScreens from './StoreScreens.vue';import SupplierScreens from './SupplierScreens.vue';import AdminScreens from './AdminScreens.vue';import {state,roles,home,go,back,restore,login,refresh,toast} from '../lib/food'
const props=defineProps({screen:String,itemId:String,initialRole:String,filter:String});const busy=ref(false),loginRole=ref(props.initialRole||'store'),credentials=ref({username:({store:'store_a',supplier:'supplier_a',admin:'admin'})[loginRole.value],password:''});const statusHeight=(uni.getWindowInfo?uni.getWindowInfo():uni.getSystemInfoSync()).statusBarHeight||24
const currentRole=computed(()=>state.user?.role||loginRole.value),authenticated=computed(()=>!!state.user&&!!state.token&&props.screen!=='login'),currentStore=computed(()=>state.stores.find(s=>s.id===state.user?.storeId));
const storeScreens=['home','product','cart','checkout','orders','detail','mine','bill','address','settings','help'],supplierScreens=['workbench','supplierOrders','picking','delivery','history'];
const authorized=computed(()=>currentRole.value==='admin'? !['home','product','cart','checkout','orders','mine','bill','address',...supplierScreens].includes(props.screen):currentRole.value==='supplier'?[...supplierScreens,'mine','settings','help'].includes(props.screen):storeScreens.includes(props.screen));
const titles={home:'订货首页',product:'食材详情',cart:'购物车',checkout:'确认订单',orders:'我的订单',detail:'订单详情',mine:'个人中心',bill:'门店账单',address:'收货信息',settings:'账号设置',help:'帮助与反馈',workbench:'供应商工作台',supplierOrders:'订单管理',picking:'备货明细',delivery:'配送任务',history:'历史订单',dashboard:'平台经营总览',products:'食材管理',productEdit:'编辑食材',stores:'门店管理',suppliers:'供应商管理',bindings:'配送关系',adminOrders:'全部订单',reports:'对账报表',settlements:'结算记录',accounts:'账号与权限',accountEdit:'编辑账号',entityEdit:'资料编辑',manage:'管理中心',feedback:'门店反馈'};
const nav=computed(()=>currentRole.value==='admin'?[{screen:'dashboard',label:'总览',icon:'home'},{screen:'products',label:'商品',icon:'box'},{screen:'adminOrders',label:'订单',icon:'order'},{screen:'manage',label:'管理',icon:'settings'}]:currentRole.value==='supplier'?[{screen:'workbench',label:'工作台',icon:'home'},{screen:'supplierOrders',label:'订单',icon:'order'},{screen:'delivery',label:'配送',icon:'truck'},{screen:'mine',label:'我的',icon:'user'}]:[{screen:'home',label:'订货',icon:'box'},{screen:'cart',label:'购物车',icon:'cart'},{screen:'orders',label:'订单',icon:'order'},{screen:'mine',label:'我的',icon:'user'}]);
const isRoot=computed(()=>nav.value.some(x=>x.screen===props.screen)||['stores','suppliers','bindings','accounts','reports','settlements','history'].includes(props.screen));
const showNav=computed(()=>!['product','checkout','detail','picking','productEdit','entityEdit','accountEdit','address','settings','help'].includes(props.screen));
function isActive(item){if(item.screen===props.screen)return true;if(item.screen==='manage')return ['stores','suppliers','bindings','accounts','reports','settlements','feedback'].includes(props.screen);if(item.screen==='mine')return props.screen==='bill';if(item.screen==='supplierOrders')return props.screen==='history';return false}
async function run(task){if(busy.value)return;busy.value=true;try{return await task()}catch(e){toast(e.message||'操作失败，请重试')}finally{busy.value=false}}provide('app',{run,busy})
function selectLogin(role){loginRole.value=role;credentials.value.username=({store:'store_a',supplier:'supplier_a',admin:'admin'})[role]}
function signIn(){run(async()=>{const u=await login(credentials.value.username,credentials.value.password);go(home(u.role),{role:u.role},true)})}
function switchRole(role){if(role===currentRole.value&&authenticated.value)return;state.user=null;state.token='';restore(role);go(state.user?home(role):'login',{role},true)}
</script>

